+ * @param {number} page One-based page number.
+ * @param {number} pageSize Number of entries per page.
+ * @returns {{items: unknown[], total: number, pageCount: number}} Page slice plus
+ *   the total entry count and the number of pages (`0` when `items` is empty).
+ * @throws {RangeError} If `page` or `pageSize` is not a positive integer.
+ */
+export function paginate(items, page, pageSize) {
+  assertPositiveInteger(page, 'page');
+  assertPositiveInteger(pageSize, 'pageSize');
+
+  const total = items.length;
+  const pageCount = Math.ceil(total / pageSize);
+  const start = (page - 1) * pageSize;
+
+  // slice() yields a fresh array, so callers can mutate the result safely.
+  const pageItems = Array.prototype.slice.call(items, start, start + pageSize);
